-- 16 October 2026 current-affairs recovery desk.
-- Every item below was checked against the linked primary official publication.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
  $$2026-10-16-wpi-september-2026$$, $$2026-10-16$$,
  $$September wholesale inflation is released on the 2022-23 WPI base$$,
  $$The Department for Promotion of Industry and Internal Trade released provisional September 2026 wholesale-price data. All-commodities WPI inflation was 11.39% year on year, and the index stood at 112.5 on the 2022-23 base.$$,
  $$This is a core economy and statistics update. It tests the distinction between WPI and CPI, the meaning of a base year, provisional versus final data, and the contribution of Primary Articles, Fuel and Power, and Manufactured Products.$$,
  $$The Wholesale Price Index tracks price movement at the wholesale stage; it is not a household cost-of-living measure. The 2022-23 base gives the comparison basket and reference period. The September release labels the estimates provisional and says the final July index remained 110.0, so students should not confuse a level of 112.5 with the year-on-year inflation rate.$$,
  $$Provisional WPI, OPPI and trial IPPI for September 2026$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2323098&lang=1&reg=3$$,
  $$Department for Promotion of Industry and Internal Trade / Press Information Bureau$$, $$2026-10-14$$,
  $$["The September 2026 WPI series uses 2022-23 as its base year.","All-commodities WPI inflation was 11.39% year on year; the index level was 112.5.","The three major WPI groups are Primary Articles, Fuel and Power, and Manufactured Products.","The September estimate is provisional, while the July 2026 WPI was final."]$$::jsonb,
  $$[{"question":"Is an index value of 112.5 the same as 11.39% inflation?","answer":"No. 112.5 is the index level on the base; 11.39% is the year-on-year change reported for September."},{"question":"Which price stage does WPI primarily track?","answer":"The wholesale stage, unlike CPI which reflects a consumer basket."}]$$::jsonb,
  $${"title":"Reading the WPI release","steps":["A base-year basket is assigned an index reference.","Wholesale prices are collected for the basket.","The index level is compared with the same month a year earlier.","The resulting percentage change is reported as WPI inflation."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-16-nsap-renamed-social-assistance$$, $$2026-10-16$$,
  $$Cabinet continues NSAP and renames its pension components$$,
  $$The Union Cabinet approved continuation of the National Social Assistance Programme for 2026-27 to 2030-31 with an outlay of ₹53,428 crore. The programme is to be renamed Pradhan Mantri Samajik Sahayata Yojana, alongside new names for its old-age, widow, disability and family-benefit components.$$,
  $$This is a high-yield social-justice and welfare-policy update. It is useful for remembering the Union's social-assistance architecture, the difference between pensions and a family-benefit scheme, and the revised disability-pension eligibility and assistance terms.$$,
  $$NSAP is a social-assistance umbrella, rather than a contributory insurance scheme. The Cabinet release retains old-age and widow pensions and the National Family Benefit Scheme in their existing form, while changing the disability-pension benchmark-disability criterion from 80% to 40% and setting assistance at ₹375 for ages 0-79 and ₹625 for ages 80 and above.$$,
  $$Cabinet approval for continuation of the National Social Assistance Programme$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2323266&lang=1&reg=3$$,
  $$Department of Rural Development / Press Information Bureau$$, $$2026-10-14$$,
  $$["NSAP is to continue for 2026-27 through 2030-31 with an outlay of ₹53,428 crore.","Its approved new umbrella name is Pradhan Mantri Samajik Sahayata Yojana.","The disability-pension benchmark-disability criterion is revised from 80% to 40%.","The release retains the old-age, widow and family-benefit components while renaming them."]$$::jsonb,
  $$[{"question":"Is NSAP a contributory insurance programme?","answer":"No. It is a social-assistance umbrella programme."},{"question":"What disability benchmark is specified in the revised eligibility criterion?","answer":"40%, replacing the earlier 80% criterion stated in the release."}]$$::jsonb,
  $${"title":"NSAP update at a glance","steps":["The Cabinet continues the social-assistance umbrella for five years.","The umbrella and components receive approved new names.","Old-age, widow and family-benefit support continue.","Disability-pension eligibility and assistance are revised."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-16-mscaro-multistate-cooperatives$$, $$2026-10-16$$,
  $$New risk-based audit-reporting order is mandated for multi-state cooperatives$$,
  $$The Ministry of Cooperation announced the Multi-State Co-operative Societies (Auditor's Report) Order, 2026, or MSCARO 2026. It introduces a uniform, structured and risk-based statutory-audit reporting framework with phased implementation.$$,
  $$This matters for cooperative governance, financial accountability and regulation. It gives students a concrete example of how statutory audit reporting can support early identification of financial stress and technology-enabled supervision.$$,
  $$A Multi-State Cooperative Society operates across more than one State and is distinct from a company. MSCARO standardises what auditors report so that compliance and risk signals can be reviewed more consistently. The release links the framework to monitoring through the Central Registrar of Cooperative Societies portal; an audit-reporting standard improves oversight but does not itself guarantee a cooperative's financial health.$$,
  $$Audit Reporting Framework for Multi-State Cooperative Societies$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2323313&lang=1&reg=3$$,
  $$Ministry of Cooperation / Press Information Bureau$$, $$2026-10-14$$,
  $$["MSCARO stands for Multi-State Co-operative Societies (Auditor's Report) Order, 2026.","It creates a uniform, structured and risk-based statutory-audit reporting framework.","The stated aims include early detection of financial stress and protection of members' funds.","Implementation is phased, and the release links monitoring to the CRCS Portal."]$$::jsonb,
  $$[{"question":"What does the 'risk-based' feature of MSCARO seek to improve?","answer":"It enables more systematic reporting and monitoring of financial and governance risks."},{"question":"Does a multi-state cooperative become a company because it has operations in several States?","answer":"No. It remains a cooperative society under its applicable legal framework."}]$$::jsonb,
  $${"title":"From audit report to cooperative oversight","steps":["Auditors use a standard reporting framework.","Reports capture governance and risk indicators.","The regulator can conduct structured and technology-enabled scrutiny.","Earlier signals can support member-fund protection and compliance action."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-16-india-siofa-accession$$, $$2026-10-16$$,
  $$India approves accession to the Southern Indian Ocean Fisheries Agreement$$,
  $$The Central Government approved India's accession to the Southern Indian Ocean Fisheries Agreement (SIOFA). The release says this will give India a regional framework for high-seas fishing and participation in scientific assessment and action against illegal, unreported and unregulated fishing.$$,
  $$This is relevant to international organisations, the Blue Economy, high-seas governance and sustainable fisheries. It is especially useful for separating an accession decision from the domestic fishing guidelines that preceded it.$$,
  $$SIOFA is a regional fisheries-management agreement for non-migratory fish stocks in a part of the Southern Indian Ocean. The official release says Indian-flagged vessels and enterprises can undertake authorised fishing within its jurisdiction, subject to the framework. It names squid, toothfish and alfonsino as examples and connects accession with preventing IUU fishing.$$,
  $$Government approval for India's accession to SIOFA$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2323370&lang=1&reg=3$$,
  $$Ministry of Fisheries, Animal Husbandry and Dairying / Press Information Bureau$$, $$2026-10-14$$,
  $$["SIOFA is the Southern Indian Ocean Fisheries Agreement.","The approval concerns India's accession to a regional high-seas fisheries framework.","The release links accession with scientific assessment and prevention of IUU fishing.","It identifies squid, toothfish and alfonsino among stocks available for authorised fishing in the framework's jurisdiction."]$$::jsonb,
  $$[{"question":"What does IUU stand for in fisheries governance?","answer":"Illegal, unreported and unregulated fishing."},{"question":"Does SIOFA concern only waters within India's territorial sea?","answer":"No. The release describes it as a high-seas regional fisheries framework."}]$$::jsonb,
  $${"title":"Why a regional fisheries agreement matters","steps":["Countries join a regional high-seas framework.","Members participate in scientific assessment and rule-making.","Authorised fishing is carried out under agreed conditions.","Cooperation supports sustainability and counters IUU fishing."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-16-idbi-bank-strategic-restructuring$$, $$2026-10-16$$,
  $$CCEA approves the strategic restructuring of IDBI Bank$$,
  $$The Cabinet Committee on Economic Affairs approved strategic restructuring of IDBI Bank. The official release describes sale of an aggregate 60.72% equity stake to a strategic buyer: 30.48% from the Government of India and 30.24% from LIC, with residual stakes of 15% and 19% respectively.$$,
  $$This is an important banking and disinvestment item. It helps students connect RBI regulation, prompt corrective action, public-sector shareholding and the multi-stage process used for a strategic sale.$$,
  $$IDBI Bank is a scheduled commercial bank regulated by the RBI. The release recalls that RBI placed it under Prompt Corrective Action in 2017 because of non-performing assets and losses, and lifted the restrictions in 2021 subject to conditions and monitoring. A strategic restructuring is not a regulatory licence: the bidder still had to satisfy RBI 'fit and proper' assessment and Ministry of Home Affairs security clearance.$$,
  $$Government approves strategic restructuring of IDBI Bank Ltd.$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2323318&lang=1&reg=3$$,
  $$Ministry of Finance / Press Information Bureau$$, $$2026-10-14$$,
  $$["IDBI Bank is a scheduled commercial bank regulated by the RBI.","The approved strategic sale covers an aggregate 60.72% stake: 30.48% from GoI and 30.24% from LIC.","The release states residual holdings of 15% for GoI and 19% for LIC.","RBI put IDBI Bank under PCA in 2017 and lifted the restrictions in 2021 subject to conditions and monitoring."]$$::jsonb,
  $$[{"question":"Which body regulates IDBI Bank as a scheduled commercial bank?","answer":"The Reserve Bank of India."},{"question":"What does PCA refer to in this banking context?","answer":"Prompt Corrective Action, a supervisory framework used by the RBI."}]$$::jsonb,
  $${"title":"Strategic restructuring and bank supervision","steps":["A bank's financial condition is supervised by the RBI.","The Government and LIC hold identified equity stakes.","A competitive process selects an eligible strategic buyer.","The transaction changes ownership while RBI regulation continues."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-16-hlcdc-demography-portal$$, $$2026-10-16$$,
  $$High-Level Committee on Demographic Changes opens its public portal$$,
  $$The High-Level Committee on Demographic Changes launched the official portal demography.mha.gov.in for public access, stakeholder submissions and data interaction. The release says Central and State/UT authorities, NGOs and individuals can provide inputs on demographic changes and related factors.$$,
  $$This is a polity, internal-security and governance item. It demonstrates a consultative digital mechanism and requires careful recall of the Committee's remit without treating public submissions as official findings.$$,
  $$The release says the Committee will analyse inputs on demographic changes, settlement patterns and underlying factors, and make recommendations regarding a legal, fair and time-bound system concerning illegal immigrants. A public portal is a channel for submissions and data interaction; it does not by itself establish the accuracy of every submission or change immigration law.$$,
  $$HLCDC official portal for public engagement and data gathering$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2323428&lang=1&reg=3$$,
  $$Ministry of Home Affairs / Press Information Bureau$$, $$2026-10-14$$,
  $$["HLCDC refers to the High-Level Committee on Demographic Changes.","Its official portal is demography.mha.gov.in.","The portal is open to Central and State/UT bodies, NGOs or institutions, and individuals for inputs and data.","The release describes the portal as a tool for engagement and analysis, not as a final demographic finding."]$$::jsonb,
  $$[{"question":"What is the primary function of the new HLCDC portal?","answer":"Public and stakeholder submission, data interaction and support for the Committee's analysis."},{"question":"Does a submission on the portal automatically become an official conclusion?","answer":"No. It is input for the Committee's analysis and recommendations."}]$$::jsonb,
  $${"title":"Digital consultation mechanism","steps":["The Committee opens a public-facing official portal.","Authorities, institutions and individuals submit information.","The Committee analyses inputs and underlying factors.","Recommendations can inform a later policy or administrative response."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-16-tdb-yeti-autonomous-logistics$$, $$2026-10-16$$,
  $$Technology Development Board supports YETI heavy-lift autonomous logistics vehicle$$,
  $$The Technology Development Board signed an agreement with ideaForge Technology for ₹151 crore in RDI Fund support for YETI, a proposed heavy-lift, long-range autonomous aerial logistics vehicle. The project aims to advance the technology from TRL 4 to TRL 9.$$,
  $$This connects science and technology, indigenous innovation finance, unmanned aerial systems and Technology Readiness Levels. It is a good test of the difference between development support for a platform and certification or routine operational deployment.$$,
  $$TDB functions under the Department of Science and Technology. The release describes the ₹302 crore project as debt-financed support for an autonomous vertical-take-off-and-landing, fixed-wing hybrid UAV. Its stated design objective is payloads up to 200 kg, range up to 200 km and operation up to 6,500 metres above mean sea level; these are project targets, not a claim of completed field deployment.$$,
  $$TDB agreement with ideaForge for YETI autonomous aerial logistics vehicle$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2323134&lang=1&reg=3$$,
  $$Technology Development Board, Department of Science and Technology / Press Information Bureau$$, $$2026-10-14$$,
  $$["TDB agreed to ₹151 crore of RDI Fund support for the YETI project.","The official release gives the total project cost as ₹302 crore and calls the support debt financing.","YETI is described as a VTOL fixed-wing hybrid UAV.","The project target is to move from TRL 4 to TRL 9, with a proposed 200 kg payload and 200 km range."]$$::jsonb,
  $$[{"question":"What does TRL measure?","answer":"Technology Readiness Level, a way to describe technological maturity."},{"question":"Does TDB funding itself establish that YETI is already in routine service?","answer":"No. The release describes a development project and stated performance targets."}]$$::jsonb,
  $${"title":"Moving an autonomous platform toward maturity","steps":["A developer proposes a logistics technology.","TDB provides RDI support through the stated financing arrangement.","Engineering and testing aim to raise the technology-readiness level.","Later regulatory and operational steps remain separate from development funding."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-10-16-sarvekshana-121-official-statistics$$, $$2026-10-16$$,
  $$MoSPI releases the 121st issue of Sarvekshana$$,
  $$The National Statistical Systems Training Academy under MoSPI released the 121st issue of Sarvekshana, its biannual Journal of Official Statistics. The issue includes research on in-kind social transfers, factory-size efficiency using ASI 2022-23, and PPS circular systematic sampling in ASI.$$,
  $$This is useful for official statistics and research-methodology questions. It offers a direct way to revise NSS, ASI, sampling concepts and the role of peer-reviewed analysis in the wider official-statistics ecosystem.$$,
  $$Sarvekshana disseminates research using National Sample Survey and other official-statistics data; it is not itself a new household survey. The release also notes highlights of ASUSE 2025 and PLFS 2025. ASI concerns industrial establishments, while ASUSE studies unincorporated-sector enterprises—two terms students should not interchange.$$,
  $$Release of the 121st issue of Sarvekshana, Journal of Official Statistics$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2323502&lang=1&reg=3$$,
  $$Ministry of Statistics and Programme Implementation / Press Information Bureau$$, $$2026-10-14$$,
  $$["Sarvekshana is a biannual Journal of Official Statistics released by NSSTA under MoSPI.","The 121st issue includes analysis using ASI 2022-23 data and a study of PPS circular systematic sampling.","It disseminates research based on NSS and other official-statistics data.","ASI and ASUSE cover different statistical domains; the release cites both in the issue's material."]$$::jsonb,
  $$[{"question":"Which ministry is associated with Sarvekshana in this release?","answer":"The Ministry of Statistics and Programme Implementation, through NSSTA."},{"question":"Is Sarvekshana itself a new National Sample Survey round?","answer":"No. It is a journal that disseminates research based on official-statistics data."}]$$::jsonb,
  $${"title":"From official data to statistical research","steps":["Official surveys and administrative data are compiled.","Researchers analyse the data and methods.","A peer-reviewed journal disseminates the work.","Students can distinguish the source survey from later analysis of it."]}$$::jsonb,
  $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
  $$2026-10-16-wpi-september-2026$$,
  $$2026-10-16-nsap-renamed-social-assistance$$,
  $$2026-10-16-mscaro-multistate-cooperatives$$,
  $$2026-10-16-india-siofa-accession$$,
  $$2026-10-16-idbi-bank-strategic-restructuring$$,
  $$2026-10-16-hlcdc-demography-portal$$,
  $$2026-10-16-tdb-yeti-autonomous-logistics$$,
  $$2026-10-16-sarvekshana-121-official-statistics$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
